import { Button, Typography } from "@mui/material";
import { ReactNode } from "react";
import CommonDataGrid, { DataGridColumn } from "@/components/common/CommonDataGrid";

const leaveRequests = [
  { id: "L001", employee: "Ava Johnson", type: "Sick Leave", status: "Pending" },
  { id: "L002", employee: "Liam Smith", type: "Casual Leave", status: "Approved" }
];

export default function LeavePage() {
  const columns: DataGridColumn<(typeof leaveRequests)[number] & { action: ReactNode }>[] = [
    { field: "id", headerName: "ID" },
    { field: "employee", headerName: "Employee" },
    { field: "type", headerName: "Type" },
    { field: "status", headerName: "Status" },
    { field: "action", headerName: "Action" }
  ];

  const rows = leaveRequests.map((request) => ({
    ...request,
    action: (
      <Button size="small" variant="outlined">
        Approve
      </Button>
    )
  }));

  return (
    <>
      <Typography variant="h4" fontWeight={700} sx={{ mb: 2 }}>
        Leave Management
      </Typography>
      <Button variant="contained" href="/leave/apply" sx={{ mb: 2 }}>
        Apply Leave
      </Button>
      <CommonDataGrid columns={columns} rows={rows} getRowId={(row) => row.id} />
    </>
  );
}
